// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address _log, address _log2) internal {
        bool firstReverted;
        try c.SetLogFile(_log) { firstReverted = false; } catch { firstReverted = true; }
        bool initReverted;
        try c.Initialized() { initReverted = false; } catch { initReverted = true; }
        bool secondReverted;
        try c.SetLogFile(_log2) { secondReverted = false; } catch { secondReverted = true; }
        assertTrue(!firstReverted && !initReverted && secondReverted);
    }

    function testFuzz_run(address _log, address _log2) public {
        vm.assume(_log.code.length == 0 && uint160(_log) > 0xffff && _log != address(this) && _log != address(c) && _log != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _log != 0x000000000000000000636F6e736F6c652e6c6f67 && _log != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _log != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(_log2.code.length == 0 && uint160(_log2) > 0xffff && _log2 != address(this) && _log2 != address(c) && _log2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _log2 != 0x000000000000000000636F6e736F6c652e6c6f67 && _log2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _log2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_log, _log2);
    }

    receive() external payable {}
}
